-- Code generated by factory from specs/sales/list-effective-price-changes/spec.yaml. DO NOT EDIT.

-- name: ListEffectivePriceChanges :many
SELECT t2.product_code, t2.new_price, t2.old_price, t2.deal_id
FROM (
    SELECT t1.product_code AS product_code, t1.new_price AS new_price, t1.old_price AS old_price, t1.deal_id AS deal_id
    FROM price_changes AS t1
    WHERE (t1.store_code = sqlc.arg(store_code)::int4)
      AND (t1.proc_date = sqlc.arg(proc_date)::date)
      AND ((t1.new_price <> t1.old_price) OR (t1.deal_id = 99999999::int8))
) AS t2
ORDER BY t2.product_code COLLATE "C"
LIMIT 1001;
